@extends('layout') @section('title','Users & permissions') @section('content')<div class="page-heading"><div><h1>Users & permissions</h1><p class="subtitle">Administrators manage all accounts. Members can only read their own financial information.</p></div></div><section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>USER</th><th>EMAIL</th><th>ROLE</th><th>CHANGE ROLE</th></tr></thead><tbody>@foreach($users as $u)<tr><td>{{$u->name}}</td><td>{{$u->email}}</td><td>{{$u->getRoleNames()->join(', ')}}</td><td><form method="post" action="/users/{{$u->id}}/role" class="d-flex gap-2" data-confirm="Update this user's access permissions?">@csrf<select aria-label="Role for {{$u->name}}" name="role" class="form-select"><option value="admin" @selected($u->hasRole('admin'))>Administrator</option><option value="member" @selected($u->hasRole('member'))>Member</option></select><button type="submit" class="btn btn-outline-secondary">Save</button></form></td></tr>@endforeach</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Add an administrator</h2></div><div class="panel-body"><form method="post" class="row g-3">@csrf @foreach(['name'=>'Full name','email'=>'Email','password'=>'Password · 12+ characters'] as $key=>$label)<div class="col-md-3"><label class="form-label">{{$label}}</label><input aria-label="{{$label}}" name="{{$key}}" type="{{$key==='name'?'text':$key}}" class="form-control" required></div>@endforeach<div class="col-md-3 d-flex align-items-end"><button type="submit" class="btn btn-primary">Create administrator</button></div></form></div></section>@endsection
